\"\"\"Minimal OpenAI Responses API client using only the Python standard library.\"\"\"

import json
import os
import sys
import urllib.error
import urllib.request

API_URL = \"https://api.openai.com/v1/responses\"
DEFAULT_MODEL = \"gpt-4.1-mini\"


class OpenAIError(Exception):
    \"\"\"Raised when the API returns an error or cannot be reached.\"\"\"


def send_prompt(prompt, model=DEFAULT_MODEL, api_key=None, instructions=None,
                store=False, timeout=60, **extra):
    \"\"\"Send a text prompt to the Responses API and return the parsed JSON.

    store=False asks OpenAI not to retain the response. The API key is read
    from the OPENAI_API_KEY environment variable unless passed explicitly.
    \"\"\"
    api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
    if not api_key:
        raise OpenAIError(\"Set OPENAI_API_KEY or pass api_key.\")

    payload = {\"model\": model, \"input\": prompt, \"store\": store}
    if instructions:
        payload[\"instructions\"] = instructions
    payload.update(extra)

    request = urllib.request.Request(
        API_URL,
        data=json.dumps(payload).encode(\"utf-8\"),
        headers={
            \"Authorization\": \"Bearer \" + api_key,
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.loads(response.read().decode(\"utf-8\"))
    except urllib.error.HTTPError as error:
        detail = error.read().decode(\"utf-8\", errors=\"replace\")
        raise OpenAIError(\"HTTP %d: %s\" % (error.code, detail)) from None
    except urllib.error.URLError as error:
        raise OpenAIError(\"Request failed: %s\" % error.reason) from None


def extract_text(response):
    \"\"\"Concatenate all output text from a Responses API result.\"\"\"
    parts = []
    for item in response.get(\"output\", []):
        if item.get(\"type\") == \"message\":
            for content in item.get(\"content\", []):
                if content.get(\"type\") == \"output_text\":
                    parts.append(content.get(\"text\", \"\"))
    return \"\".join(parts)


def ask(prompt, **kwargs):
    \"\"\"Send a prompt and return just the reply text.\"\"\"
    return extract_text(send_prompt(prompt, **kwargs))


if __name__ == \"__main__\":
    text = \" \".join(sys.argv[1:]) or sys.stdin.read()
    try:
        print(ask(text))
    except OpenAIError as error:
        sys.exit(str(error))
EOF
python3 -c \"import ast;ast.parse(open('/workspace/openai_client.py').read())\" && echo ok"

